  <a href="#main-content" class="skip-to-content">Skip to content</a>
  <main id="main-content" role="main">
    <article class="poster" id="poster" aria-label="UNICEF global education campaign advocacy poster">
      <div class="grain"></div>
      <div class="content">
        <header class="brand animate">
          <div class="brand-left">
            <div class="emblem" aria-hidden="true">
              <svg viewBox="0 0 64 64" fill="none" aria-hidden="true">
                <circle cx="32" cy="19" r="10" fill="white"/>
                <path d="M16 52c4-12 11-19 16-19s12 7 16 19" stroke="white" stroke-width="7" stroke-linecap="round"/>
                <path d="M13 30c-4 5-5 12-2 18M51 30c4 5 5 12 2 18" stroke="white" stroke-width="5" stroke-linecap="round"/>
                <path d="M20 10c-7 4-12 11-13 20M44 10c7 4 12 11 13 20" stroke="white" stroke-width="4" stroke-linecap="round" opacity=".8"/>
              </svg>
            </div>
            <span>UNICEF Education</span>
          </div>
          <div class="sdg">Aligned with SDG 4 • Quality Education</div>
        </header>
        <section class="hero" id="crisis-overview" aria-labelledby="hero-title">
          <div class="hero-copy animate delay-1">
            <div class="eyebrow">The global education crisis</div>
            <h1 class="headline" id="hero-title">Every child deserves <span>to learn.</span></h1>
            <p class="subhead">Millions of children are still denied their right to inclusive, quality education — but urgent, collective action can change that.</p>
          </div>
          <div class="stat-card animate delay-2">
            <div class="stat-label">Children out of school worldwide</div>
            <div class="big-number">250 <small>million</small></div>
            <p class="stat-copy">A number too large to ignore — and a future we can still rewrite.</p>
            <div class="child-arc" aria-hidden="true"><span class="arm one"></span><span class="arm two"></span><span class="head"></span><span class="body"></span></div>
          </div>
        </section>
        <section class="metrics" aria-label="Key global education metrics">
          <div class="metric animate delay-3"><strong>70%</strong><span>of 10-year-olds in low- and middle-income countries cannot read and understand a simple text.</span></div>
          <div class="metric animate delay-3"><strong>190+</strong><span>countries and territories where UNICEF works to improve education outcomes.</span></div>
          <div class="metric animate delay-4"><strong>2.5×</strong><span>girls in crisis settings are more likely than boys to be excluded from education.</span></div>
          <div class="metric animate delay-4"><strong>~49%</strong><span>children with disabilities in low-income countries are out of school.</span></div>
        </section>
        <section class="main-grid" aria-label="Barriers and UNICEF focus areas">
          <section class="barriers" id="barriers" aria-labelledby="barriers-title">
            <h2 class="section-title" id="barriers-title">Barriers that stop learning</h2>
            <div class="barrier-list">
              <div class="barrier"><div class="icon">!</div><div><h3>Conflict & emergencies</h3><p>Schools are destroyed, teachers displaced, and children forced to learn through trauma and instability.</p></div></div>
              <div class="barrier"><div class="icon">$</div><div><h3>Poverty</h3><p>Fees, uniforms, supplies, transport and child labour keep classrooms out of reach.</p></div></div>
              <div class="barrier"><div class="icon">♀</div><div><h3>Gender inequality</h3><p>Social norms and safety risks still block girls from enrolling, staying and completing school.</p></div></div>
              <div class="barrier"><div class="icon">♿</div><div><h3>Disability exclusion</h3><p>Nearly half of children with disabilities in low-income countries never set foot in a classroom.</p></div></div>
              <div class="barrier"><div class="icon">☔</div><div><h3>Climate shocks</h3><p>Floods, droughts and extreme heat disrupt schooling for the most vulnerable children first.</p></div></div>
            </div>
          </section>
          <section class="focus" id="unicef-focus-areas" aria-labelledby="focus-title">
            <div class="focus-card">
              <h2 class="section-title" id="focus-title">How UNICEF helps children learn</h2>
              <div class="pill-grid">
                <div class="pill"><b>Early childhood foundations</b><small>Pre-primary education and school readiness.</small></div>
                <div class="pill"><b>Inclusive classrooms</b><small>Support for children with disabilities and marginalized groups.</small></div>
                <div class="pill"><b>Girls’ education</b><small>Removing barriers to enrolment, safety and completion.</small></div>
                <div class="pill"><b>Learning in emergencies</b><small>Continuity during conflict, displacement and disasters.</small></div>
                <div class="pill"><b>Digital learning</b><small>Technology that expands access and improves quality.</small></div>
                <div class="pill"><b>Adolescent skills</b><small>Preparation for work, civic life and lifelong learning.</small></div>
              </div>
            </div>
            <div class="mini-chart" aria-labelledby="chart-title">
              <h3 id="chart-title">What exclusion looks like</h3>
              <div class="chart-wrap"><canvas id="educationChart" role="img" aria-label="Bar chart comparing learning poverty at 70 percent and children with disabilities out of school at approximately 49 percent"></canvas></div>
            </div>
          </section>
        </section>
        <section class="action" id="call-to-action" aria-label="Call to action">
          <div class="action-card">
            <h2>Education is a right — not a privilege.</h2>
            <p>Together, governments, communities, organizations and individuals can help ensure no child is left behind.</p>
          </div>
          <div class="steps">
            <h2>What can be done</h2>
            <div class="step"><i>1</i><span>Invest in inclusive, quality learning for every child.</span></div>
            <div class="step"><i>2</i><span>Protect education during crises and climate shocks.</span></div>
            <div class="step"><i>3</i><span>Support UNICEF’s work to reach the children furthest behind.</span></div>
          </div>
        </section>
        <footer class="footer">
          <p class="source">Source: Adapted from UNICEF Education programme information and campaign brief. Key figures include 250 million children out of school globally; 70% learning poverty by age 10 in low- and middle-income countries; UNICEF education programmes in 190+ countries and territories.</p>
          <div class="tagline">Every child. Every right. Every classroom.</div>
        </footer>
      </div>
    </article>
  </main>
  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'light';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count || '0');
        var suffix = el.dataset.suffix || '';
        var start = performance.now();
        function tick(now) {
          var p = Math.min(1, (now - start) / 900);
          el.textContent = Math.round(target * p).toLocaleString() + suffix;
          if (p < 1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      });
    }
    animateCounters();
    function downloadImage() {
      var node = document.getElementById('poster') || document.getElementById('main-content');
      htmlToImage.toPng(node, { pixelRatio: 1, backgroundColor: '#eaf9ff' }).then(function(dataUrl) {
        var link = document.createElement('a');
        link.download = 'every-child-deserves-to-learn.png';
        link.href = dataUrl;
        link.click();
      });
    }
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js library not loaded - check CDN inclusion'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) { console.error('Chart initialization failed for ' + canvasId, error); return null; }
      }
    };
    function initEducationChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      ChartManager.safeInit('educationChart', {
        type: 'bar',
        data: {
          labels: ['Learning poverty', 'Disability exclusion'],
          datasets: [{
            label: 'Share of children affected',
            data: [70, 49],
            backgroundColor: ['#00aeef', '#ffb347'],
            borderRadius: 14,
            borderSkipped: false
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: { enabled: true, callbacks: { label: function(context) { return context.parsed.y + '% affected'; } } }
          },
